RAFTER = pal("#6a4a30", "#563a24", "#40291a", "#2a1a10")
WINDOW = pal("#fff2c8", "#f8dc96", "#e8bc70", "#c8945a")        # late-day light through old glass (light .. dark)
MULLION = H("#5a3e26")
IRON = pal("#5a5a5e", "#3e3e44", "#2a2a30", "#18181c")
FELT = [pal("#b8503e", "#963a2e", "#742a22", "#501c18"),        # maroon
        pal("#e0b050", "#c8923a", "#9c6c26", "#6a4618"),        # mustard
        pal("#5a8a5a", "#3e6e46", "#2c5234", "#1c3824"),        # forest green
        pal("#5a6e9a", "#3e507c", "#2c3a5e", "#1c2640"),        # navy
        pal("#f0e6cc", "#d8ccae", "#b4a688", "#8a7c62")]        # cream
OLD_SHIRTS = [pal("#e8dcc0", "#cfc2a4", "#a89a7e", "#7a6e58"), pal("#8a9ab8", "#62749a", "#46567a", "#2e3a56"),
              pal("#b87a5a", "#965a40", "#744230", "#502c20"), pal("#9aa47a", "#7a8458", "#5c6440", "#3e442a"),
              pal("#6a6470", "#4e4856", "#38343e", "#24222a"), pal("#c89a5a", "#a87a40", "#84602e", "#5a401e"),
              pal("#b06060", "#8e4646", "#6c3434", "#4a2424")]
HAT = pal("#5a4a3c", "#3e3228", "#2a221a")                       # felt hats (dark brown .. near black)
ERA_TIERS = 1
ERA_TIER_H = 9
ERA_YEARS = ["1948", "1953", "1957", "1961", "1964", "1969"]   # made-up old seasons, no names


def felt_banner(px, bx, top, w, h, c, ink, year, stripes=2):
    """A hanging felt banner: a wooden rod, a star, an old year, stripes near the notched bottom (no letters)."""
    px.rect(bx - 2, top - 1, bx + w + 1, top - 1, RAFTER[1])     # rod
    px.put(bx - 2, top - 1, RAFTER[0])
    for y in range(top, top + h):
        for x in range(bx, bx + w):
            k = 1
            if x == bx:
                k = 0
            if x == bx + w - 1:
                k = 2
            px.put(x, y, c[k])
    mid = bx + (w - 1) / 2.0
    for d in range(3):                                          # swallow-tail bottom
        for x in range(bx, bx + w):
            if abs(x - mid) > d * 2 + 1:
                px.put(x, top + h + d, c[2] if x > mid else c[1])
    for s in range(stripes):
        yy = top + h - 3 - 2 * s
        px.rect(bx + 1, yy, bx + w - 2, yy, ink)
    cx = bx + w // 2
    for dy, row in enumerate(("..X..", "XXXXX", ".XXX.", ".X.X.")):
        for dx, ch in enumerate(row):
            if ch == "X":
                px.put(cx - 3 + dx, top + 2 + dy, ink)
    number(px, year, cx - 8, top + 8, ink)


def era_person(px, x, y, rnd, t, standing=False, arms_up=False):
    """A spectator of the old days: muted clothes, often a felt hat or a flat cap."""
    person(px, x, y, rnd, t, standing, arms_up, shirts=OLD_SHIRTS)
    r = rnd.random()
    hx = x + 1
    if r < 0.30:                                                # felt hat: crown and brim
        hc = rnd.choice(HAT)
        px.rect(hx, y - 1, hx + 2, y, hc)
        px.rect(hx - 1, y + 1, hx + 3, y + 1, mix(hc, (0, 0, 0), 0.2))
        px.put(hx, y - 1, mix(hc, (255, 255, 255), 0.15))
    elif r < 0.45:                                              # flat cap
        cc = rnd.choice(OLD_SHIRTS)
        px.rect(hx, y, hx + 2, y, cc[2])
        px.put(hx + 3, y + 1, cc[3])


def era_window(px, x0, y0, x1, y1):
    """A tall arched window of warm late-day light with iron mullions."""
    cxw = (x0 + x1) / 2.0
    r2 = ((x1 - x0) / 2.0) ** 2
    ay = y0 + 5                                                 # where the arch meets the straight sides

    def inside(x, y):
        return y >= ay or (x - cxw) ** 2 + (y - ay) ** 2 * 2.6 <= r2

    for y in range(y0 - 2, y1 + 1):
        for x in range(x0 - 1, x1 + 2):
            if inside(x, y) and x0 <= x <= x1 and y >= y0 - 1:
                k = 0 if (x - x0) + (y - y0) // 2 < 7 else 1
                if y > y1 - 6:
                    k = 2
                px.put(x, y, WINDOW[k])
            elif any(inside(x + ex, y + ey) and x0 <= x + ex <= x1 for ex, ey in ((1, 0), (-1, 0), (0, 1))):
                px.put(x, y, MULLION)                           # frame round the glass
    for y in range(y0 - 1, y1 + 1):
        for x in (int(cxw), int(cxw) + 1):
            if inside(x, y):
                px.put(x, y, MULLION)
    for yy in (y0 + 8, y0 + 16):
        for x in range(x0, x1 + 1):
            px.put(x, yy, MULLION)
    px.rect(x0 - 1, y1 + 1, x1 + 1, y1 + 1, WAINSCOT[1])         # sill
    px.rect(x0 - 1, y1 + 2, x1 + 1, y1 + 2, WAINSCOT[3])
    for y in range(y0, y1 + 2):                                 # a soft glow on the plaster round the window
        for x in (x0 - 4, x0 - 3, x0 - 2, x1 + 2, x1 + 3, x1 + 4):
            px.blend(x, y, WINDOW[1], 0.16)


def era_grand_backdrop(seed=52):
    """The game shows rows ~50-100 at 1280 x 720 (the top bar covers ~50-68), so the landmarks sit low: the
    balcony up high (seen on taller screens and in previews), the windows, banners, clock and score board in rows
    ~52-82, one tier of folding bleachers under them, the kick board at the floor."""
    rnd = random.Random(seed)
    px = bd_canvas(PLASTER[1])
    wall_bot = 84                                               # plaster down to here, then the dado and bleachers
    for y in range(wall_bot):                                   # plaster, darker toward the top, trowel marks
        for x in range(BD_W):
            k = 1 if y > 46 else 2
            if (x * 7 + y * 13) % 29 == 0:
                k = min(3, k + 1)
            elif (x * 5 + y * 3) % 31 == 0:
                k = max(0, k - 1)
            px.put(x, y, PLASTER[k])
    # ceiling: dark wood with rafter ends
    px.rect(0, 0, BD_W - 1, 4, RAFTER[2])
    px.rect(0, 5, BD_W - 1, 5, RAFTER[3])
    for x in range(0, BD_W, 24):
        px.rect(x, 5, x + 3, 8, RAFTER[1])
        px.put(x, 5, RAFTER[0])
        px.rect(x, 9, x + 3, 9, mix(PLASTER[2], RAFTER[3], 0.4))
    # balcony: a wooden running track high on the wall, spectators leaning on its iron rail
    bt = 36
    x = 3
    while x < BD_W - 6:
        if rnd.random() < 0.45:
            era_person(px, x, bt - 9, rnd, 0)
        x += rnd.choice((5, 6, 7, 9, 12))
    px.rect(0, bt - 3, BD_W - 1, bt - 3, IRON[1])
    px.rect(0, bt - 2, BD_W - 1, bt - 2, IRON[3])
    for x in range(2, BD_W, 6):
        px.put(x, bt - 1, IRON[2])
    px.rect(0, bt, BD_W - 1, bt + 6, WAINSCOT[1])
    px.rect(0, bt, BD_W - 1, bt, WAINSCOT[0])
    px.rect(0, bt + 5, BD_W - 1, bt + 6, WAINSCOT[3])
    for x in range(0, BD_W, 16):                                # fascia panels
        px.rect(x, bt + 2, x, bt + 4, WAINSCOT[2])
        px.put(x + 1, bt + 2, WAINSCOT[0])
    for x in range(0, BD_W):                                    # its shadow on the plaster
        px.blend(x, bt + 7, RAFTER[3], 0.35)
        px.blend(x, bt + 8, RAFTER[3], 0.15)
    # tall arched windows of late-day light, one every 64 texels (the strip repeats every 384)
    for wx in range(6, BD_W, 64):
        era_window(px, wx, 55, wx + 15, 80)
    # felt banners between the windows (years and stars only) ...
    banner_x = [30, 94, 222, 286, 350]
    for k, bx in enumerate(banner_x):
        c = FELT[(0, 1, 4, 3, 2)[k]]                               # maroon, mustard, cream, navy, green
        felt_banner(px, bx, 58, 20, 19, c, FELT[4][0] if k != 2 else FELT[0][1], ERA_YEARS[k], stripes=2 if k % 2 == 0 else 1)
    # ... and in the middle, between two windows, the round wall clock over a hand-flipped score board
    ccx, ccy, cr = 174, 60, 6
    for y in range(ccy - cr - 1, ccy + cr + 2):
        for x in range(ccx - cr - 1, ccx + cr + 2):
            d = (x - ccx) ** 2 + (y - ccy) ** 2
            if d <= (cr - 1) ** 2:
                px.put(x, y, H("#f8f0dc"))
            elif d <= (cr + 1) ** 2:
                px.put(x, y, RAFTER[3] if (x - ccx) + (y - ccy) > 0 else RAFTER[1])
    for k in range(4):                                          # quarter ticks
        a = k * math.pi / 2
        px.put(ccx + int(round(math.cos(a) * (cr - 2))), ccy + int(round(math.sin(a) * (cr - 2))), RAFTER[1])
    px.rect(ccx, ccy - 4, ccx, ccy, H("#2a1a10"))               # hands
    px.rect(ccx, ccy, ccx + 3, ccy, H("#2a1a10"))
    sx0, sx1, sy0, sy1 = 156, 192, 69, 80
    px.rect(ccx, ccy + cr + 2, ccx, sy0 - 1, IRON[2])           # the clock's wire down to the board
    px.rect(sx0, sy0, sx1, sy1, WAINSCOT[2])
    px.rect(sx0, sy0, sx1, sy0, WAINSCOT[0])
    px.rect(sx0, sy0, sx0, sy1, WAINSCOT[1])
    px.rect(sx1, sy0, sx1, sy1, WAINSCOT[3])
    px.rect(sx0, sy1, sx1, sy1, WAINSCOT[3])
    for cx0 in (sx0 + 3, sx1 - 13):                             # blank cream flip cards (no digits: never
        px.rect(cx0, sy0 + 2, cx0 + 10, sy0 + 8, H("#f0e6cc"))  # read as the live score under the HUD)
        px.rect(cx0 + 5, sy0 + 2, cx0 + 5, sy0 + 8, H("#b4a688"))
        px.rect(cx0, sy0 + 5, cx0 + 10, sy0 + 5, H("#d8ccb0"))  # the flip fold across each card
        px.rect(cx0, sy0 + 9, cx0 + 10, sy0 + 9, WAINSCOT[3])
    px.rect(sx0 + 16, sy0 + 4, sx0 + 20, sy0 + 6, FELT[0][0])  # possession lamp
    # dark wood dado behind the top of the bleachers
    px.rect(0, wall_bot, BD_W - 1, BD_H - 1, WAINSCOT[2])
    px.rect(0, wall_bot, BD_W - 1, wall_bot, WAINSCOT[0])
    px.rect(0, wall_bot + 1, BD_W - 1, wall_bot + 1, WAINSCOT[1])
    # folding wooden bleachers, half full
    top0 = BD_H - 7 - ERA_TIERS * ERA_TIER_H
    for t in range(ERA_TIERS):
        y0 = top0 + t * ERA_TIER_H
        px.rect(0, y0 + 2, BD_W - 1, y0 + ERA_TIER_H - 4, RISER[2 if t < ERA_TIERS - 1 else 1])
        px.rect(0, y0 + 2, BD_W - 1, y0 + 2, RISER[3])
        px.rect(0, y0 + ERA_TIER_H - 3, BD_W - 1, y0 + ERA_TIER_H - 3, BLEACH[0])
        px.rect(0, y0 + ERA_TIER_H - 2, BD_W - 1, y0 + ERA_TIER_H - 2, BLEACH[1])
        px.rect(0, y0 + ERA_TIER_H - 1, BD_W - 1, y0 + ERA_TIER_H - 1, BLEACH[3])
        for x in range(0, BD_W, 32):                            # plank ends on the seats
            px.put(x, y0 + ERA_TIER_H - 2, BLEACH[3])
        x = rnd.randint(0, 4)
        density = 0.70
        while x < BD_W - 2:
            if rnd.random() < density:
                standing = rnd.random() < 0.08
                era_person(px, x, y0 + ERA_TIER_H - 10 - (2 if standing else 0), rnd, t, standing,
                           arms_up=rnd.random() < 0.10)
            x += rnd.choice((5, 6, 6, 7))
    # front: a wooden kick board along the floor
    fy = BD_H - 7
    px.rect(0, fy, BD_W - 1, BD_H - 1, WAINSCOT[1])
    px.rect(0, fy, BD_W - 1, fy, WAINSCOT[0])
    px.rect(0, BD_H - 2, BD_W - 1, BD_H - 1, WAINSCOT[2])
    px.rect(0, BD_H - 1, BD_W - 1, BD_H - 1, WAINSCOT[3])
    for x in range(0, BD_W, 24):
        px.rect(x, fy + 1, x, BD_H - 3, WAINSCOT[3])
        px.put(x + 1, fy + 1, WAINSCOT[0])
    return haze_rows(px.image(), H("#5a4632"), 0.30, 0.10)     # warm and a little faded: the old days


# ============================================================================= Phase 10 era court (P10-05)
# Legends, Chapter 2 (the Fathers): look "era_fathers", a blacktop under lights. Same conventions as era_grand
# (64 x 64 seamless floor tile, 384 x 100 backdrop repeating in x; the game shows rows ~52-100 at 1280 x 720 and the
# HUD bar covers ~54-68, so the landmarks sit in rows ~56-99). A made-up night playground: no teams, arenas,
# leagues, brands, letters or digits (nothing that could read as a score under the HUD). Its court_looks.gd row has
# no twist (the legends match brings the era twist) and it never joins the Quick Game COURT list.
# Not the MIDNIGHT look (blue-violet night, moon and stars, neon shop fronts, street lamps, an empty street): here a
# warm sodium-lit summer night, a wine-red city glow with no stars, tall light towers with floodlight banks, a
# made-up skyline of plain towers behind an elevated rail line (a lit train on it), a tall fence and a crowd on
# aluminium stands, with a speaker stack table between them (a night tournament).
#   era_fathers  NIGHT PARK  warm charcoal asphalt with tar-sealed cracks, patches and lamp-warm glints; wine sky
#                            glowing orange-red at the horizon; plain dark towers with a few lit windows; a steel
#                            rail viaduct; three light towers (4 x 2 floodlight banks, halos); chain-link fence;
#                            two tiers of aluminium stands full of a 2000s crowd (baggy tees, fitted caps, durags);
#                            speaker stacks on a folding table; a low concrete curb at the floor. At 1280 x 720 the
#                            game shows rows ~54-100 and the HUD band covers ~54-68: the blocks and the lit train
#                            sit behind the band (seen through it), the floodlights at its lower edge

# --- era_fathers floor
NIGHTPARK_ASP = pal("#5c5452", "#544c4b", "#4c4544", "#443e3e")   # warm charcoal asphalt (sodium-lit)
NIGHTPARK_GLINT = pal("#9a8466", "#7e6c58")                         # aggregate catching the warm lamps
NIGHTPARK_TAR = pal("#2c2626", "#3c3534")                           # tar-sealed cracks (soft, so the tile never
                                                                    # shows a repeating mark)
NIGHTPARK_PATCH = pal("#4a4342", "#47403f")                         # a re-paved patch, a little darker


def era_fathers_floor(seed=61):
    """Warm charcoal asphalt in soft blotches, light and dark aggregate, lamp-warm glints, two re-paved patches and
    tar-sealed cracks. Lighter than MIDNIGHT's floor so blue and red jerseys and the ball stay readable."""
    rnd = random.Random(seed)
    px = Pix(TILE, TILE, NIGHTPARK_ASP[1], wrap_y=True)
    noise_tones(px, NIGHTPARK_ASP, rnd, cuts=(0.80, 0.50, 0.22))
    for (x0, y0, w, h) in ((6, 40, 15, 9), (38, 8, 12, 7)):     # re-paved patches: a little darker, soft edges
        for y in range(y0, y0 + h):
            for x in range(x0, x0 + w):
                edge = x in (x0, x0 + w - 1) or y in (y0, y0 + h - 1)
                if not edge or rnd.random() < 0.5:
                    px.blend(x, y, NIGHTPARK_PATCH[0], 0.30 if edge else 0.55)
    for _ in range(110):                                        # aggregate: light and dark specks
        px.put(rnd.randrange(TILE), rnd.randrange(TILE), NIGHTPARK_ASP[rnd.choice((0, 0, 3, 3))])
    for _ in range(18):                                         # warm glints
        px.put(rnd.randrange(TILE), rnd.randrange(TILE), NIGHTPARK_GLINT[rnd.choice((0, 1, 1))])
    for _ in range(2):                                          # tar-sealed cracks (wider and darker than hairlines)
        crack(px, rnd.randrange(TILE), rnd.randrange(TILE), rnd.randint(10, 18), rnd, NIGHTPARK_TAR[1])
    return px.image()


# --- era_fathers backdrop
FSKY = pal("#160e1c", "#1e1224", "#2a162c", "#3a1c30", "#522436", "#6e2e38", "#8a3c36")  # wine night .. city glow
FTOWER = [pal("#2e2230", "#281d2a", "#221824", "#1c141e"), pal("#33262e", "#2c2028", "#251b22", "#1e161c")]
FTOWER_NEAR = [pal("#3a2a30", "#33242a", "#2c1f25", "#24191e"), pal("#40302c", "#382926", "#302320", "#281d1b")]
FWIN = pal("#ffd88a", "#f0a85a", "#d8d0c0", "#8a5a40")           # warm lit windows (and a few pale ones)
STEEL = pal("#5a4e56", "#463c44", "#342c34", "#241e26")          # the viaduct and the light towers
SODIUM = pal("#fffbe6", "#ffe6a0", "#ffc860", "#c8823a")         # floodlights (core .. warm halo)
ALU = pal("#e8e4e0", "#bcb6b4", "#8c8688", "#5e585e")            # aluminium stands
NFENCE2 = pal("#d8c8b8", "#a8988c", "#786a66", "#4e4446")        # chain-link lit warm from the court
CURB = pal("#8a7c72", "#6e625c", "#564c48", "#3e3634")
SPEAKER = pal("#4a4248", "#343038", "#24202a", "#141218")
STREET_SHIRTS = [pal("#ffffff", "#e6e4ec", "#b4b2c0", "#7a7888"),   # baggy white tees (most of them)
                 pal("#ffffff", "#e6e4ec", "#b4b2c0", "#7a7888"),
                 pal("#ff7a6a", "#d8283a", "#951833", "#5a0e2a"),   # plain jerseys in bright colours (no numbers)
                 pal("#78b8ff", "#2f74e0", "#1f479e", "#172a66"),
                 pal("#ffe07a", "#f0b02a", "#b8781a", "#7a4a10"),
                 pal("#8ad86a", "#3a9a46", "#26703a", "#184a28"),
                 pal("#6a6470", "#46404e", "#302c36", "#1e1c24"),   # black hoodies
                 pal("#c8a8e8", "#8a5ab8", "#5e3a8a", "#3a2458")]
DURAG = pal("#2a2a6a", "#1a1a3a"), pal("#8a1a2a", "#4a0e18"), pal("#1e1e22", "#0e0e10"), pal("#e8e8f0", "#a8a8b8")
FITTED = [pal("#d8283a", "#951833"), pal("#2f74e0", "#1f479e"), pal("#1e1e22", "#0e0e10"), pal("#f0b02a", "#b8781a"),
          pal("#3a9a46", "#26703a")]
FATHERS_TIER_H = 8
FATHERS_POLES = (40, 168, 296)                                   # light towers (one every 128 texels)
FATHERS_STANDS = ((0, 30), (50, 154), (182, 240), (306, 384))   # stand sections (x0, x1), gaps at the poles
FATHERS_SPEAKERS = 248                                           # the speaker table, between the stands


def street_person(px, x, y, rnd, t, standing=False, arms_up=False):
    """A spectator of the 2000s: a baggy tee or a plain jersey, often a fitted cap (flat brim) or a durag."""
    person(px, x, y, rnd, t, standing, arms_up, shirts=STREET_SHIRTS)
    r = rnd.random()
    hx = x + 1
    if r < 0.28:                                                # fitted cap with a flat brim
        cc = rnd.choice(FITTED)
        px.rect(hx, y - 1, hx + 2, y, cc[0])
        px.put(hx + 2, y, cc[1])
        px.rect(hx - 1, y + 1, hx + 3, y + 1, cc[1])
    elif r < 0.42:                                              # durag, tail at the back
        dc = rnd.choice(DURAG)
        px.rect(hx, y, hx + 2, y, dc[0])
        px.put(hx + 2, y + 1, dc[1])
        px.put(hx + 3, y + 2, dc[1])


def light_tower(px, x, top=63):
    """A tall steel light tower: a 5 x 2 floodlight bank in a frame (rows ~63-69, at the HUD band's lower edge, so it
    shows at 1280 x 720; its halo spills over the fence and the stands) on a 2-texel pole."""
    px.rect(x, top + 6, x + 1, BD_H - 4, STEEL[1])               # pole
    px.rect(x, top + 6, x, BD_H - 4, STEEL[0])
    for y in range(top + 10, BD_H - 6, 6):                       # climbing pegs
        px.put(x + 2, y, STEEL[2])
    bx0, bx1 = x - 9, x + 10
    px.rect(bx0, top, bx1, top + 5, STEEL[3])                    # bank frame
    px.rect(bx0, top, bx1, top, STEEL[1])
    px.rect(bx0 + 2, top + 6, bx1 - 2, top + 6, STEEL[2])        # the bracket under it
    for row in range(2):
        for col in range(5):
            lx, ly = bx0 + 1 + col * 4, top + 1 + row * 2
            px.rect(lx, ly, lx + 2, ly + 1, SODIUM[1])
            px.put(lx, ly, SODIUM[0])
            px.put(lx + 1, ly, SODIUM[0])


def era_fathers_backdrop(seed=62):
    """Back to front: the wine night sky and its city glow, far towers, nearer blocks, the rail viaduct (a lit
    train on part of it), the light towers, the fence, the stands with the crowd and the speaker table, the curb.
    The top-left texel is the sky's top colour (the game fills above the strip with it)."""
    rnd = random.Random(seed)
    px = bd_canvas(FSKY[0])
    sky(px, 0, 80, FSKY)
    # far towers: plain flat-topped slabs (tops rows 22-52), dim, a few lit windows; no famous shapes
    x = 0
    k = 0
    while x < BD_W:
        w = rnd.choice((16, 20, 24, 28, 34))
        if BD_W - (x + w) < 16:
            w = BD_W - x
        top = rnd.randint(22, 52)
        c = FTOWER[k % 2]
        for xx in range(x, x + w):
            for y in range(top, 82):
                px.put(xx, y, c[0] if xx == x else (c[2] if xx >= x + w - 2 else c[1]))
        if rnd.random() < 0.35:                                  # a rooftop box or a water tank
            bx = x + rnd.randint(3, max(3, w - 9))
            px.rect(bx, top - 3, bx + 5, top - 1, c[2])
            px.rect(bx + 1, top - 1, bx + 1, top - 1, c[3])
        for wy in range(top + 3, 80, 3):
            for wx in range(x + 2, x + w - 2, 3):
                if rnd.random() < 0.16:
                    px.put(wx, wy, FWIN[rnd.choice((0, 1, 1, 2, 3))])
        x += w
        k += 1
    img = haze_rows(px.image(), H("#6e2e38"), 0.35, 0.30)        # the city glow pushes them back
    px = from_img(img)
    # nearer blocks: lower and darker (tops rows 50-57), more lit windows, flat roofs with a parapet
    x = 0
    k = 0
    while x < BD_W:
        w = rnd.choice((26, 32, 38, 44))
        if BD_W - (x + w) < 26:
            w = BD_W - x
        top = rnd.randint(50, 57)
        c = FTOWER_NEAR[k % 2]
        for xx in range(x, x + w):
            for y in range(top, 84):
                px.put(xx, y, c[0] if xx == x else (c[3] if xx >= x + w - 2 else c[1]))
        px.rect(x, top, x + w - 1, top, c[0])
        for wy in range(top + 3, 62, 4):
            for wx in range(x + 3, x + w - 4, 5):
                if rnd.random() < 0.45:
                    wc = FWIN[rnd.choice((0, 1, 1, 3))]
                    px.rect(wx, wy, wx + 2, wy + 1, wc)
                else:
                    px.rect(wx, wy, wx + 2, wy + 1, c[3])
        x += w
        k += 1
    # the elevated rail line: a steel deck (rows 64-69) with an X-braced girder, columns every 48, a lit train
    dy0, dy1 = 64, 69
    tx0, tx1 = 196, 312                                          # the train, on part of the line
    for x in range(tx0, tx1):
        car_i = (x - tx0) // 29
        u = (x - tx0) % 29
        if u == 28:
            continue                                             # gap between cars
        for y in range(58, dy0):
            px.put(x, y, STEEL[1] if y > 58 else STEEL[0])
        if 2 <= u <= 25 and u % 5 != 0:
            px.rect(x, 60, x, 61, FWIN[1] if (car_i + u // 5) % 3 else FWIN[0])
    px.rect(0, dy0, BD_W - 1, dy0, STEEL[0])
    px.rect(0, dy0 + 1, BD_W - 1, dy1, STEEL[2])
    for x in range(BD_W):
        u = x % 8
        for y in range(dy0 + 1, dy1 + 1):
            if (y - dy0 - 1) in (u * 4 // 8, 4 - u * 4 // 8):     # X bracing
                px.put(x, y, STEEL[1])
    px.rect(0, dy1 + 1, BD_W - 1, dy1 + 1, STEEL[3])
    for cx in range(20, BD_W, 48):
        px.rect(cx, dy1 + 1, cx + 2, 86, STEEL[2])
        px.put(cx, dy1 + 2, STEEL[1])
    # the ground behind the fence: a dark strip of grass and path
    px.rect(0, 84, BD_W - 1, BD_H - 1, H("#1e1a1c"))
    # light towers and their halos (behind the fence, over the city)
    for lx in FATHERS_POLES:
        light_tower(px, lx)
    for lx in FATHERS_POLES:
        glow(px, lx + 1, 66, 44, SODIUM[2], 0.40)
        glow(px, lx + 1, 66, 24, SODIUM[2], 0.45)
        glow(px, lx + 1, 66, 12, SODIUM[1], 0.70)
    # the fence: chain-link from row 73 down (its top rail just under the HUD band), lit warm from the court
    ft = 73
    for y in range(ft + 2, BD_H - 4):
        for x in range(BD_W):
            u, v = (x + y) % 5, (x - y) % 5
            if u == 0 or v == 0:
                px.blend(x, y, NFENCE2[1] if u == 0 else NFENCE2[2], 0.30 if u == 0 else 0.24)
    for x in range(BD_W):
        px.put(x, ft, NFENCE2[0])
        px.put(x, ft + 1, NFENCE2[2])
    for x in range(8, BD_W, 64):
        px.rect(x, ft - 1, x + 1, BD_H - 4, NFENCE2[1])
        px.rect(x, ft - 1, x, BD_H - 4, NFENCE2[0])
        px.put(x - 1, ft - 1, NFENCE2[2])
        px.put(x + 2, ft - 1, NFENCE2[2])
    # aluminium stands, two tiers (rows 80-95), full of the crowd; sections leave gaps at the light towers
    top0 = BD_H - 5 - 2 * FATHERS_TIER_H
    for x0, x1 in FATHERS_STANDS:
        for t in range(2):
            y0 = top0 + t * FATHERS_TIER_H
            px.rect(x0, y0 + 2, x1 - 1, y0 + FATHERS_TIER_H - 3, SPEAKER[2])            # open riser (dark)
            px.rect(x0, y0 + FATHERS_TIER_H - 2, x1 - 1, y0 + FATHERS_TIER_H - 2, ALU[0])  # bench, lit edge
            px.rect(x0, y0 + FATHERS_TIER_H - 1, x1 - 1, y0 + FATHERS_TIER_H - 1, ALU[2])
            for xx in range(x0 + 3, x1 - 1, 16):                                       # legs
                px.put(xx, y0 + FATHERS_TIER_H - 1, ALU[3])
            x = x0 + rnd.randint(0, 3)
            while x < x1 - 5:
                if rnd.random() < 0.80:
                    standing = rnd.random() < 0.15
                    street_person(px, x, y0 + FATHERS_TIER_H - 10 - (2 if standing else 0), rnd, t, standing,
                                  arms_up=rnd.random() < 0.14)
                x += rnd.choice((5, 6, 6, 7))
        px.rect(x0, top0 + 2 * FATHERS_TIER_H, x1 - 1, top0 + 2 * FATHERS_TIER_H, ALU[1])  # foot rail
    # people standing along the fence in the gaps (by the light towers)
    for gx0, gx1 in ((31, 49), (155, 181), (241, 305)):
        x = gx0 + 1
        while x < gx1 - 5:
            if rnd.random() < 0.55 and not (FATHERS_SPEAKERS - 2 <= x <= FATHERS_SPEAKERS + 34):
                street_person(px, x, BD_H - 17, rnd, 1, True, arms_up=rnd.random() < 0.2)
            x += rnd.choice((6, 7, 8))
    # the speaker table: a folding table with two speaker stacks (cones only, no badge or text)
    sx = FATHERS_SPEAKERS
    px.rect(sx, 87, sx + 31, 88, ALU[1])
    px.rect(sx, 87, sx + 31, 87, ALU[0])
    px.rect(sx + 2, 89, sx + 2, BD_H - 5, ALU[3])
    px.rect(sx + 29, 89, sx + 29, BD_H - 5, ALU[3])
    for cx0 in (sx + 1, sx + 21):
        px.rect(cx0, 73, cx0 + 9, 86, SPEAKER[1])
        px.rect(cx0, 73, cx0 + 9, 73, SPEAKER[0])
        px.rect(cx0 + 9, 74, cx0 + 9, 86, SPEAKER[3])
        for (ccy, cr) in ((77, 2.6), (83, 3.2)):
            ccx = cx0 + 4.5
            for y in range(int(ccy - cr - 1), int(ccy + cr + 2)):
                for x in range(cx0 + 1, cx0 + 9):
                    d = math.hypot(x + 0.5 - ccx, y + 0.5 - ccy)
                    if d <= cr * 0.45:
                        px.put(x, y, SPEAKER[0])
                    elif d <= cr:
                        px.put(x, y, SPEAKER[3])
                    elif d <= cr + 0.8:
                        px.put(x, y, SPEAKER[2])
    px.rect(sx + 12, 84, sx + 19, 86, SPEAKER[2])               # the deck between the speakers
    px.put(sx + 14, 84, SODIUM[2])
    # the low concrete curb at the floor
    cy = BD_H - 4
    px.rect(0, cy, BD_W - 1, BD_H - 1, CURB[1])
    px.rect(0, cy, BD_W - 1, cy, CURB[0])
    px.rect(0, BD_H - 1, BD_W - 1, BD_H - 1, CURB[3])
    for x in range(0, BD_W, 32):
        px.rect(x, cy + 1, x, BD_H - 2, CURB[2])
    # warm light falling from the towers: a soft cone down over the fence and the crowd, a wide halo on the stands
    for lx in FATHERS_POLES:
        for y in range(70, BD_H - 4):
            f = (y - 70) / float(BD_H - 74)
            hw = 9 + 14 * f
            for x in range(int(lx + 1 - hw), int(lx + 2 + hw)):
                edge = 1.0 - abs(x - lx - 1) / hw
                px.blend(x, y, SODIUM[1], 0.16 * (1 - 0.6 * f) * min(1.0, edge * 2.5))
        glow(px, lx + 1, 86, 44, SODIUM[2], 0.20)
    return px.image()



# ============================================================================= Phase 11 era court (P11-06)
# Legends, Chapter 3 (the Present): look "era_present", a made-up modern arena. Same conventions as the other era
# looks (64 x 64 seamless floor tile, 384 x 100 backdrop repeating in x; the game shows rows ~52-100 at 1280 x 720 and
# the HUD bar covers ~54-68). No team, arena, league, logo, sponsor, letter or digit anywhere: the ribbon boards carry
# abstract stripes and chevrons only. Its court_looks.gd row has no twist and it never joins the Quick Game COURT list.
# Not GOLD HALL (warm honey maple, navy seats, gold banners with years, gold LED), not the gym (orange maple, wooden
# bleachers) and not Memphis' soul gym (an old packed gym): here cool ash-grey wide planks under a clear gloss, a dark
# charcoal bowl, black seats, cool white light, and ribbon boards in the era colour (teal, a first guess until the
# P11-05 look check) with a coral accent; fans hold up phone lights.
#   era_present  (BIG STAGE, owner)  wide 8-texel ash planks in cool greige with a fine seam, staggered
#                            joints, a bright gloss edge and long soft light streaks (the arena lights in the varnish);
#                            a near-black roof with a light ring, a dim upper deck, a teal ribbon board with white
#                            slashes (rows ~65-69, at the HUD band's lower edge), a lower bowl of black seats with LED
#                            step lights in the aisles, a courtside LED board (teal chevrons, coral bars) and a dark
#                            padded front with a thin teal trim

# --- era_present floor
ASH = pal("#bab2a7", "#b5ada2", "#b0a89d", "#aba398")             # cool greige ash planks (lit .. shade)
ASH_SEAM = H("#7e766e")
ASH_GRAIN = H("#968e84")
ASH_GLOSS = H("#f4f2ee")
PRESENT_PLANK = 8                                                 # texels per plank (wide modern boards)


def era_present_floor(seed=71):
    """Wide ash planks (7 texels + a fine seam) in four close cool tones, staggered joints (1-2 per plank row per
    tile, at least 22 apart), faint grain, a bright gloss edge on every plank and two long soft gloss streaks that
    wrap in x (the arena lights in a clear finish). Mid-light so the white lines, the teal key and both jerseys read."""
    rnd = random.Random(seed)
    px = Pix(TILE, TILE, ASH[1], wrap_y=True)
    for r in range(TILE // PRESENT_PLANK):
        y = r * PRESENT_PLANK
        while True:
            n = rnd.choice((1, 2))
            js = sorted(rnd.randrange(TILE) for _ in range(n))
            gaps = [(js[(k + 1) % n] - js[k]) % TILE or TILE for k in range(n)]
            if min(gaps) >= 22:
                break
        for k in range(n):
            x0, L = js[k], gaps[k]
            base = ASH[rnd.choice((0, 1, 1, 2, 2, 3))]
            for dx in range(L):
                x = x0 + dx
                for dy in range(PRESENT_PLANK - 1):
                    c = base
                    if dy == 0:
                        c = mix(base, ASH_GLOSS, 0.14)
                    elif dy == PRESENT_PLANK - 2:
                        c = mix(base, ASH_SEAM, 0.05)
                    if dx == L - 1:
                        c = mix(base, ASH_SEAM, 0.28)
                    px.put(x, y + dy, c)
            for _ in range(max(1, L // 10)):                     # faint grain lines along the plank
                gx = x0 + rnd.randint(1, max(1, L - 10))
                gy = y + rnd.randint(1, PRESENT_PLANK - 3)
                for q in range(rnd.randint(4, 9)):
                    if (gx + q - x0) % TILE < L - 1:
                        px.put(gx + q, gy, mix(base, ASH_GRAIN, 0.25))
        for x in range(TILE):
            px.put(x, y + PRESENT_PLANK - 1, mix(ASH[3], ASH_SEAM, 0.30))
    for gy in (13, 42):                                          # long soft gloss streaks (wrap in x)
        for x in range(TILE):
            px.blend(x, gy, ASH_GLOSS, 0.16 + 0.08 * math.sin(2 * math.pi * x / TILE + gy))
    for _ in range(8):                                           # gloss specks (2 texels, along the planks)
        x, y = rnd.randrange(TILE), rnd.randrange(TILE)
        if y % PRESENT_PLANK not in (PRESENT_PLANK - 1, 0):
            px.blend(x, y, ASH_GLOSS, 0.6)
            px.blend(x + 1, y, ASH_GLOSS, 0.35)
    return px.image()


# --- era_present backdrop
PBOWL = pal("#2a2d36", "#20232b", "#181a21", "#0e1015")          # the charcoal bowl (lit .. roof black)
PSEAT = pal("#3a3d46", "#2a2c34", "#1c1e25", "#121318")          # black seats
TEAL = pal("#b8fff4", "#3ee0d0", "#16a8a0", "#0c6a68")           # the era colour (first guess) on the LED
CORAL = pal("#ffd0b8", "#ff7a5a", "#d8483a", "#8a2a2a")          # the accent
PLIGHT = H("#e8f4ff")                                            # cool white arena light
PRESENT_SHIRTS = [pal("#ffffff", "#e4eaf2", "#aab4c4", "#6a7488"),   # white tees
                  pal("#7af0e0", "#22b8ac", "#16807c", "#0c4e4e"),   # teal (the home colour, no logo)
                  pal("#7af0e0", "#22b8ac", "#16807c", "#0c4e4e"),
                  pal("#5c5c72", "#34343f", "#1f1e2a", "#121019"),   # black hoodies
                  pal("#ff9a7a", "#f05a40", "#b0382e", "#6a2020"),   # coral
                  pal("#a8b0c0", "#7a8296", "#545a6c", "#363a48"),   # grey
                  pal("#78b8ff", "#2f74e0", "#1f479e", "#172a66"),
                  pal("#ffe080", "#f0b830", "#b07818", "#6c4410")]
PRESENT_TIER_H = 9
PRESENT_AISLES = (56, 184, 312)                                  # one aisle every 128 texels


def slashes(px, y0, y1, step, fg, bg, phase=0, width=2):
    """A ribbon strip: bg with forward slashes of fg (abstract, no letters), every `step` texels."""
    px.rect(0, y0, BD_W - 1, y1, bg)
    for x0 in range(phase - (y1 - y0), BD_W + step, step):
        for dy in range(y1 - y0 + 1):
            for t in range(width):
                px.put(x0 + (y1 - y0 - dy) + t, y0 + dy, fg)


def era_present_backdrop(seed=72):
    """Back to front: the near-black roof with a ring of cool lights, the dim upper deck, the teal ribbon board, the
    lower bowl (black seats, fans, phone lights, LED step lights in the aisles), the courtside LED board and the
    padded front. The top-left texel is the roof's colour (the game fills above the strip with it)."""
    rnd = random.Random(seed)
    px = bd_canvas(PBOWL[3])
    # the roof: a ring of light fixtures (rows 6-8) and a faint catwalk truss (rows 14-17)
    for x in range(4, BD_W, 12):
        px.rect(x, 6, x + 3, 7, PLIGHT)
        px.rect(x, 8, x + 3, 8, mix(PLIGHT, PBOWL[3], 0.5))
    for x in range(BD_W):
        px.put(x, 14, PBOWL[2])
        px.put(x, 17, PBOWL[2])
        if (x % 6) in (0, 5):
            px.put(x, 15, PBOWL[2])
            px.put(x, 16, PBOWL[2])
    # the upper deck (rows 22-64): steep dim tiers of tiny fans, a few phone lights
    for y in range(22, 65):
        for x in range(BD_W):
            px.put(x, y, PBOWL[2] if (y - 22) % 4 else PBOWL[3])
    for y in range(24, 63, 4):
        for x in range(rnd.randint(0, 2), BD_W, 2):
            if rnd.random() < 0.78:
                c = rnd.choice(PRESENT_SHIRTS)[rnd.choice((1, 2))]
                px.put(x, y, mix(c, PBOWL[2], 0.62))
                px.put(x, y + 1, mix(rnd.choice(SKIN)[1], PBOWL[2], 0.66))
    for _ in range(40):                                          # phone lights up in the deck
        px.put(rnd.randrange(BD_W), rnd.randint(24, 63), H("#ffffff") if rnd.random() < 0.6 else PLIGHT)
    img = haze_rows(px.image(), H("#0e1015"), 0.30, 0.0)
    px = from_img(img)
    # the ribbon board between the decks (rows 64-70): trims, teal with white slashes, a coral bar every 64
    px.rect(0, 64, BD_W - 1, 64, PBOWL[0])
    slashes(px, 65, 69, 8, TEAL[0], TEAL[2], phase=2)
    for x in range(0, BD_W, 64):
        px.rect(x + 28, 65, x + 35, 69, CORAL[1])
        px.rect(x + 28, 65, x + 35, 65, CORAL[0])
    px.rect(0, 70, BD_W - 1, 72, PBOWL[3])
    # the lower bowl (rows 73-90): two tiers of black seats full of fans, aisles with LED step lights
    top0 = 73
    for t in range(2):
        y0 = top0 + t * PRESENT_TIER_H
        px.rect(0, y0, BD_W - 1, y0 + PRESENT_TIER_H - 3, PSEAT[2])
        px.rect(0, y0, BD_W - 1, y0, PSEAT[3])
        px.rect(0, y0 + PRESENT_TIER_H - 2, BD_W - 1, y0 + PRESENT_TIER_H - 2, PSEAT[0])
        px.rect(0, y0 + PRESENT_TIER_H - 1, BD_W - 1, y0 + PRESENT_TIER_H - 1, PSEAT[3])
        for ax in PRESENT_AISLES:
            px.rect(ax, y0, ax + 5, y0 + PRESENT_TIER_H - 1, PBOWL[1])
            px.rect(ax, y0 + PRESENT_TIER_H - 2, ax + 5, y0 + PRESENT_TIER_H - 2, PBOWL[0])
            px.put(ax, y0 + PRESENT_TIER_H - 1, TEAL[1])     # LED step lights at both ends of a step
            px.put(ax + 5, y0 + PRESENT_TIER_H - 1, TEAL[1])
        x = rnd.randint(0, 4)
        while x < BD_W:
            if any(ax - 5 <= x % BD_W <= ax + 6 for ax in PRESENT_AISLES):
                x += 2
                continue
            if rnd.random() < 0.93:
                standing = rnd.random() < 0.14
                arms = rnd.random() < 0.20
                hy = y0 + PRESENT_TIER_H - 10 - (2 if standing else 0)
                person(px, x, hy, rnd, t, standing, arms_up=arms, shirts=PRESENT_SHIRTS)
                if arms and rnd.random() < 0.5:                  # a phone light held up
                    px.put(x + rnd.choice((0, 4)), hy, H("#ffffff"))
            x += rnd.choice((5, 6, 6, 7))
    # cool light from the roof: soft wide beams down over the bowl (blended)
    for bx in (24, 152, 280):
        for y in range(18, 90):
            half = 5 + (y - 18) * 0.18
            cx = bx + 30 + (y - 18) * 0.10
            for x in range(int(cx - half), int(cx + half) + 1):
                px.blend(x, y, PLIGHT, 0.07 * (1 - abs(x - cx) / (half + 1)))
    # courtside: a teal trim, the LED board (rows 92-96: teal chevrons, coral bars, teal dots), the padded front
    px.rect(0, 91, BD_W - 1, 91, TEAL[3])
    chevrons(px, 92, 96, 14, TEAL[1], H("#080a0e"), phase=6)
    for x in range(0, BD_W, 96):
        px.rect(x + 40, 92, x + 55, 96, CORAL[2])
        for k in range(0, 16, 4):
            px.rect(x + 41 + k, 93, x + 42 + k, 95, CORAL[1])
        px.rect(x, 92, x, 96, H("#22252e"))                      # board panel joints
    for x in range(3, BD_W, 8):
        if px.get(x, 94) == tuple(H("#080a0e")):
            px.put(x, 94, TEAL[2])
    px.rect(0, 97, BD_W - 1, 97, TEAL[2])
    px.rect(0, 98, BD_W - 1, BD_H - 1, PBOWL[1])
    px.rect(0, BD_H - 1, BD_W - 1, BD_H - 1, PBOWL[3])
    return px.image()


# ============================================================================= Phase 12 era court (P12-06)
# Legends, Chapter 4 (the New Generation): look "era_next", a made-up arena of the future. Same conventions as the
# other era looks (64 x 64 seamless floor tile, 384 x 100 backdrop repeating in x; the game shows rows ~52-100 at
# 1280 x 720 and the HUD bar covers ~54-68). No team, arena, league, logo, sponsor, letter or digit anywhere. The era
# colours are the owner's (look check 1): electric lime + violet on near-black, chrome as the third tone.
# Not MIDNIGHT (an outdoor night blacktop: sky, skyline, fence, magenta key) and not BIG STAGE (light ash wood, a lit
# bowl, teal ribbon and LED boards): here a dark glass floor in big panels, lime glowing lines and a violet key, a
# black dome with a lattice, violet light rings hanging on chrome cables, a dark crowd lit only by phone lights, a
# chrome rail and a lime edge light along the floor.
#   era_next  (NEON DOME, first idea)  near-black glass panels (16-texel squares, a fine lit seam), a soft violet
#                            sheen of the rings in the glass, a few cool reflection streaks; a black dome with a faint
#                            violet lattice and three small far light rings (rows ~47-56), a violet light line along
#                            the deck edge (row 62), a dark crowd in steep tiers with white and lime phone lights
#                            (rows 64-85), three big violet light rings hanging in front of it on chrome cables
#                            (rows ~61-74, just under the HUD band), a chrome rail on posts with smoked glass
#                            (rows 85-93) and a lime edge light at floor level (rows 95-97)

# --- era_next floor
GLASS = pal("#24222f", "#201e2b", "#1c1a27", "#181622")           # near-black glass panels (lit .. shade)
GLASS_SEAM = H("#3a3850")
GLASS_SHEEN = H("#6a3cc0")                                        # the violet rings in the glass
GLASS_GLINT = H("#c8d0e8")
NEXT_PANEL = 16                                                   # texels per glass panel (square)


def era_next_floor(seed=81):
    """Near-black glass in 16-texel square panels (four close tones), a fine lit seam on the top and left edges of
    each panel and a darker one under it, soft violet sheen blotches (the hanging rings seen in the glass) and two
    faint cool reflection streaks along x; seamless both ways. Dark and calm so the lime lines and the violet key carry the
    court and both jerseys pop."""
    rnd = random.Random(seed)
    px = Pix(TILE, TILE, GLASS[1], wrap_y=True)
    n = TILE // NEXT_PANEL
    for r in range(n):
        for q in range(n):
            base = GLASS[rnd.choice((0, 1, 1, 2, 2, 3))]
            x0, y0 = q * NEXT_PANEL, r * NEXT_PANEL
            for dy in range(NEXT_PANEL):
                for dx in range(NEXT_PANEL):
                    c = base
                    if dy == 0 or dx == 0:
                        c = mix(base, GLASS_SEAM, 0.55)
                    elif dy == 1 or dx == 1:
                        c = mix(base, (8, 6, 14), 0.35)
                    px.put(x0 + dx, y0 + dy, c)
    sheen = periodic_noise(TILE, TILE, 2, rnd, octaves=2)        # soft violet sheen (wraps both ways)
    for y in range(TILE):
        for x in range(TILE):
            t = max(0.0, sheen[y, x] - 0.52) * 0.38
            if t > 0:
                px.blend(x, y, GLASS_SHEEN, min(t, 0.10))
    for k, gy in enumerate((9, 41)):                              # faint long reflection streaks (wrap in x)
        for x in range(TILE):
            t = 0.05 + 0.03 * math.sin(2 * math.pi * x / TILE + 2.0 * k)
            px.blend(x, gy, GLASS_GLINT, t)
            px.blend(x, gy + 1, GLASS_GLINT, t * 0.5)
    for _ in range(6):                                            # tiny glints on the glass
        x, y = rnd.randrange(TILE), rnd.randrange(TILE)
        if x % NEXT_PANEL > 2 and y % NEXT_PANEL > 2:
            px.blend(x, y, GLASS_GLINT, 0.35)
    return px.image()


# --- era_next backdrop
NDOME = pal("#1a1726", "#131120", "#0e0c18", "#08070f")           # the dome (lit .. roof black)
NSEAT = pal("#22202e", "#1a1824", "#13111b", "#0c0b12")           # dark seats
LIME = pal("#f0ffc0", "#b8ff3a", "#7ad81e", "#3e7a12")           # the era's lime glow
VIOLET = pal("#e8c8ff", "#a65cff", "#6a2ad0", "#3a1478")         # the era's violet glow
CHROME = pal("#f4f6fa", "#c4ccd8", "#848ea0", "#444a58")         # chrome (rails, cables)
NEXT_SHIRTS = [pal("#5c5a72", "#3a3848", "#26242f", "#16151c"),   # dark tees and hoodies (the crowd sits in the dark)
               pal("#5c5a72", "#3a3848", "#26242f", "#16151c"),
               pal("#6a5a8a", "#463a62", "#2e2644", "#1c172c"),   # violet
               pal("#5a6a3a", "#3c4a26", "#283218", "#18200e"),   # lime, dim
               pal("#686e7a", "#464a54", "#2e3138", "#1c1e22")]   # grey
NEXT_TIER_H = 7
NEXT_CROWD = (64, 85)                                             # the crowd's rows (3 tiers)
NEXT_RINGS = ((40, 67, 30, 5, 1.0), (168, 68, 32, 5, 1.0), (296, 66, 29, 5, 1.0),   # (cx, cy, rx, ry, brightness)
              (104, 52, 17, 3, 0.55), (232, 50, 16, 3, 0.55), (360, 53, 17, 3, 0.55))


def light_ring(px, cx, cy, rx, ry, k):
    """A hanging light ring seen from a little below: an ellipse 1-2 texels thick in violet, the near (lower) half
    brightest, with a soft glow round it and two chrome cables up into the dome. k: brightness (far rings dimmer)."""
    for cx_off in (-rx * 0.7, rx * 0.7):                          # cables
        x = int(round(cx + cx_off))
        for y in range(0, int(cy - ry * math.sqrt(1 - 0.49)) + 1):
            px.blend(x, y, CHROME[2 if k >= 1.0 else 3], 0.45 * k)
    for y in range(int(cy - ry * 3), int(cy + ry * 3) + 1):     # glow
        for x in range(int(cx - rx - 6), int(cx + rx + 7)):
            d = math.hypot((x - cx) / (rx + 0.01), (y - cy) / (ry + 0.01))
            g = max(0.0, 1.0 - abs(d - 1.0) * 1.6)
            if g > 0:
                px.blend(x, y, VIOLET[2], 0.30 * k * g * g)
    steps = int(2 * math.pi * rx * 2)
    for s in range(steps):
        a = 2 * math.pi * s / steps
        x, y = cx + rx * math.cos(a), cy + ry * math.sin(a)
        near = math.sin(a) > 0                                    # the lower half faces us
        c = VIOLET[0] if near and k >= 1.0 else VIOLET[1]
        if k < 1.0:
            c = mix(VIOLET[1], NDOME[2], 0.30)
        px.put(round(x), round(y), c)
        if near and k >= 1.0:
            px.put(round(x), round(y) + 1, VIOLET[1])


def era_next_backdrop(seed=82):
    """Back to front: the black dome with a faint violet lattice and the far light rings, the deck edge (a chrome lip
    and a violet light line), the dark crowd in steep tiers (phone lights in white and lime), the near violet light
    rings hanging in front of it on chrome cables, the chrome rail with smoked glass and the lime edge light on the
    floor. The top-left texel is the dome's colour (the game fills above the strip with it)."""
    rnd = random.Random(seed)
    px = bd_canvas(NDOME[3])
    top0, bot = NEXT_CROWD
    # the dome (rows 0-61): rows lighten downward, a lattice of horizontal struts and curved ribs (wrap in x)
    for y in range(0, top0):
        c = mix(NDOME[3], NDOME[1], y / float(top0))
        for x in range(BD_W):
            px.put(x, y, c)
    for y in (14, 28, 40, 50, 58):
        for x in range(BD_W):
            px.blend(x, y, VIOLET[3], 0.22 + y / 220.0)
    for x0 in range(0, BD_W, 32):
        for y in range(0, top0 - 2):
            bend = 10 * math.sin(math.pi * y / 124.0)
            px.blend(x0 + bend, y, VIOLET[3], 0.32)
            px.blend(x0 + 16 - bend, y, VIOLET[3], 0.18)
    for ring in NEXT_RINGS:                                       # the far rings (behind the deck edge)
        if ring[4] < 1.0:
            light_ring(px, *ring)
    # the deck edge (rows 61-63): a chrome lip and a violet light line
    px.rect(0, top0 - 3, BD_W - 1, top0 - 3, CHROME[3])
    px.rect(0, top0 - 2, BD_W - 1, top0 - 2, VIOLET[1])
    px.rect(0, top0 - 1, BD_W - 1, top0 - 1, NSEAT[3])
    for x in range(BD_W):
        px.blend(x, top0 - 4, VIOLET[2], 0.30)
        px.blend(x, top0 - 1, VIOLET[2], 0.40)
    # the crowd (rows 64-85): steep dark tiers, dim fans, phone lights
    tiers = (bot - top0 + 1) // NEXT_TIER_H + 1
    for t in range(tiers):
        y0 = top0 + t * NEXT_TIER_H
        y1 = min(y0 + NEXT_TIER_H - 1, bot)
        if y0 > bot:
            break
        px.rect(0, y0, BD_W - 1, y1, NSEAT[2])
        px.rect(0, y1, BD_W - 1, y1, NSEAT[3])
        px.rect(0, y0, BD_W - 1, y0, NSEAT[1])
        x = rnd.randint(0, 3)
        while x < BD_W:
            if rnd.random() < 0.90:
                standing = rnd.random() < 0.12
                arms = rnd.random() < 0.22
                hy = y0 + NEXT_TIER_H - 9 - (2 if standing else 0)
                sub = Pix(7, 14, NSEAT[2])                        # draw the fan, then dim him into the dark
                person(sub, 1, 3, random.Random(rnd.random()), t, standing, arms_up=arms, shirts=NEXT_SHIRTS)
                dim = 0.58 - 0.06 * t
                for sy in range(14):
                    for sx in range(7):
                        c = sub.get(sx, sy)
                        yy = hy - 3 + sy
                        if c != tuple(NSEAT[2]) and y0 <= yy <= y1:
                            px.put(x - 1 + sx, yy, mix(c, NSEAT[3], dim))
                if arms and rnd.random() < 0.6 and hy >= y0:     # a phone light held up
                    lc = LIME[0] if rnd.random() < 0.35 else H("#ffffff")
                    lx = x + rnd.choice((0, 4))
                    px.put(lx, hy, lc)
                    px.blend(lx, hy - 1, lc, 0.35)
            x += rnd.choice((5, 6, 6, 7))
    for _ in range(60):                                           # more phone lights all over the dark bowl
        px.put(rnd.randrange(BD_W), rnd.randint(top0 + 1, bot - 1), LIME[0] if rnd.random() < 0.3 else H("#ffffff"))
    for ring in NEXT_RINGS:                                       # the near rings: their light on the crowd, then them
        if ring[4] >= 1.0:
            glow(px, ring[0], ring[1] + 6, ring[2] + 8, VIOLET[2], 0.16)
    for ring in NEXT_RINGS:
        if ring[4] >= 1.0:
            light_ring(px, *ring)
    # the chrome rail (rows 85-93): smoked glass panels between posts, a round chrome tube on top
    px.rect(0, 88, BD_W - 1, 93, mix(NSEAT[3], VIOLET[3], 0.25))
    for x in range(BD_W):
        px.put(x, 88, mix(CHROME[3], NSEAT[3], 0.3))
        if x % 24 == 10:
            px.blend(x, 90, CHROME[2], 0.35)                      # a glint on the glass
    px.rect(0, 85, BD_W - 1, 85, mix(CHROME[3], NSEAT[3], 0.4))
    px.rect(0, 86, BD_W - 1, 86, CHROME[0])
    px.rect(0, 87, BD_W - 1, 87, CHROME[2])
    for x in range(0, BD_W, 24):                                  # posts
        px.rect(x, 86, x + 1, 93, CHROME[2])
        px.put(x, 86, CHROME[0])
        px.rect(x + 1, 87, x + 1, 93, CHROME[3])
    # the floor-level base and the lime edge light (rows 94-99)
    px.rect(0, 94, BD_W - 1, BD_H - 1, NDOME[3])
    px.rect(0, 95, BD_W - 1, 95, LIME[2])
    px.rect(0, 96, BD_W - 1, 96, LIME[0])
    px.rect(0, 97, BD_W - 1, 97, LIME[1])
    for x in range(BD_W):
        px.blend(x, 94, LIME[2], 0.40)
        px.blend(x, 93, LIME[2], 0.18)
        px.blend(x, 98, LIME[3], 0.45)
        px.blend(x, 99, LIME[3], 0.20)
    return px.image()


