def era_ids(args):
    """The era looks to write: `--era ID` (ID = a chapter id like "fathers", or the look id "era_fathers") only that
    one (P10-05: so a new chapter's court never rewrites an older one); `--era` alone (or a full run) every one."""
    if "--era" in args:
        i = args.index("--era")
        if i + 1 < len(args) and not args[i + 1].startswith("--"):
            lid = args[i + 1] if args[i + 1].startswith("era_") else "era_" + args[i + 1]
            if lid not in ERA_MAKERS:
                sys.exit("--era: unknown era look '%s' (%s)" % (args[i + 1], ", ".join(ERA_MAKERS)))
            return [lid]
    return list(ERA_MAKERS)


def era_outputs(ids=None):
    """P9-05, P10-05: {path: image} for the era court looks (floor + backdrop); ids: only these looks."""
    out = {}
    for lid, (fl, bd) in ERA_MAKERS.items():
        if ids is not None and lid not in ids:
            continue
        out[os.path.join(COURTS, lid + "_floor.png")] = fl()
        out[os.path.join(COURTS, lid + "_backdrop.png")] = bd()
    return out


def write_era(args):
    """The era outputs (era_ids(args)); --era-preview DIR also writes DIR/<look>_tiles.png (the backdrop at 3x, the
    floor 3 x 3)."""
    os.makedirs(COURTS, exist_ok=True)
    ids = era_ids(args)
    era = era_outputs(ids)
    for path, img in era.items():
        img.save(path, optimize=True)
        print("wrote %s %s %d bytes" % (os.path.relpath(path, ROOT), img.size, os.path.getsize(path)))
    if "--era-preview" in args:
        i = args.index("--era-preview")
        d = args[i + 1]
        for lid in ids:
            bd = era[os.path.join(COURTS, lid + "_backdrop.png")]
            t3 = tile_test(era[os.path.join(COURTS, lid + "_floor.png")], n=3, zoom=2)
            pv = Image.new("RGB", (BD_W * 3, BD_H * 3 + 8 + t3.size[1]), (20, 18, 28))
            pv.paste(bd.resize((BD_W * 3, BD_H * 3), Image.NEAREST), (0, 0))
            pv.paste(t3, (0, BD_H * 3 + 8))
            out = os.path.join(d, lid + "_tiles.png")
            pv.save(out)
            print("wrote", out)
    if "--era-sheet" in args:
        i = args.index("--era-sheet")
        for lid in ids:
            era_sheet(lid, era, args[i + 1])


ERA_SHEET_COMPARE = {"era_next": ("midnight", "era_present")}   # the looks it must not read as (shown under it)


def era_sheet(lid, era, shots):
    """P12-06: docs/art/<look>_preview.png for the owner's look check: the game's angled shot (shots/<look>.png, from
    -- --court <look> --shots, hoops_900.png), the flat shot (shots/<look>_flat.png, add --view flat), the whole
    backdrop at 3x, the floor tile 3 x 3 at 2x, and the looks it must not read as (shots/<other>.png) at half size."""
    def shot(name):
        path = os.path.join(shots, name + ".png")
        return Image.open(path).convert("RGB") if os.path.exists(path) else None
    name = ERA_LOOKS.get(lid, {}).get("name", lid)
    bd = era[os.path.join(COURTS, lid + "_backdrop.png")]
    t3 = tile_test(era[os.path.join(COURTS, lid + "_floor.png")], n=3, zoom=2)
    main_s, flat_s = shot(lid), shot(lid + "_flat")
    others = [(o, shot(o)) for o in ERA_SHEET_COMPARE.get(lid, ())]
    bg = (16, 14, 24)
    H_LBL = 36
    rows_h = H_LBL + 720 + H_LBL + 360 + H_LBL + BD_H * 3 + 8 + (H_LBL + 360 if others else 0) + 8
    pv = Image.new("RGB", (1280 if BD_W * 3 <= 1280 else BD_W * 3, rows_h), bg)
    y = 0
    label(pv, "%s  (%s, proposed name)  angled view  -- --court %s --shots" % (lid, name, lid), 8, y + 4, scale=2)
    y += H_LBL
    if main_s:
        pv.paste(main_s.resize((1280, 720)), (0, y))
    y += 720
    label(pv, "flat view  |  floor tile 3 x 3 at 2x", 8, y + 4, scale=2)
    y += H_LBL
    if flat_s:
        pv.paste(flat_s.resize((640, 360)), (0, y))
    pv.paste(t3.crop((0, 0, min(t3.size[0], 600), min(t3.size[1], 360))), (660, y))
    y += 360
    label(pv, "whole backdrop at 3x (the game shows rows ~52-100; the HUD covers ~54-68)", 8, y + 4, scale=2)
    y += H_LBL
    pv.paste(bd.resize((BD_W * 3, BD_H * 3), Image.NEAREST), (0, y))
    y += BD_H * 3 + 8
    if others:
        label(pv, "for comparison: " + "  |  ".join(o.upper() for o, _ in others), 8, y + 4, scale=2)
        y += H_LBL
        for k, (o, im) in enumerate(others):
            if im:
                pv.paste(im.resize((640, 360)), (k * 640, y))
    out = os.path.join(ROOT, "docs", "art", lid + "_preview.png")
    pv.save(out, optimize=True)
    print("wrote %s %s %d bytes" % (os.path.relpath(out, ROOT), pv.size, os.path.getsize(out)))


# ----------------------------------------------------------------------------- ball

BALL = pal("#ffb070", "#f0761e", "#b84a16", "#702a12")
BALL_SEAM = pal("#6a2c10", "#3e1a0a")
BALL_OUT = H("#2a120c")
BALL_HI = H("#ffe0b8")
BALL_R = 5.5             # 11 texels across
FRAMES = 4


# The special balls (P8-06, star rewards ball_1..3): the same 4 spin frames of 16 x 16, ball 11 texels across, the
# same light and seams; only the colours change. "panels": a second palette on two opposite quarters (two-tone).
# "sparkle": a 4-point glint at the upper right on frames 0 and 2 (it twinkles as the ball spins).
#   ball_1  SKY         two-tone sky blue and white, navy seams
#   ball_2  NIGHT GLOW  deep indigo with glowing mint seams
#   ball_3  GOLD        polished gold, dark seams, a twinkling glint
BALL_STYLES = {
    "ball_1": {"name": "SKY", "body": pal("#d8f0ff", "#7ac0f0", "#3a86c8", "#1e4e86"),
               "panels": pal("#ffffff", "#e6ecf6", "#aebacc", "#6a7890"), "seam": pal("#1c3a6a", "#0c1a36"),
               "out": H("#0c1630"), "hi": H("#ffffff")},
    "ball_2": {"name": "NIGHT GLOW", "body": pal("#6a6ab8", "#3c3c86", "#26265e", "#16163a"),
               "seam": pal("#8affd0", "#3ad8a0"), "out": H("#08081a"), "hi": H("#d0d0ff")},
    "ball_3": {"name": "GOLD", "body": pal("#fff4b8", "#f2c84a", "#c08a22", "#6e4a10"),
               "seam": pal("#6a440e", "#3a2406"), "out": H("#2a1a06"), "hi": H("#ffffff"), "sparkle": True},
}


def ball_frames(style=None):
    """4 frames of a ball spinning forward (about the screen-depth axis tilted a little), 90 degrees per cycle.
    style: a BALL_STYLES entry (None = the game's orange ball, ball.png)."""
    st = style or {}
    body = st.get("body", BALL)
    panels = st.get("panels")
    seam_c = st.get("seam", BALL_SEAM)
    out_c = st.get("out", BALL_OUT)
    hi_c = st.get("hi", BALL_HI)
    out = Image.new("RGBA", (16 * FRAMES, 16), (0, 0, 0, 0))
    L = P.LIGHT
    cx = cy = 8.0
    tilt = P.rot_x(math.radians(-25)) @ P.rot_y(math.radians(20))
    for f in range(FRAMES):
        spin = P.rot_z(-math.radians(90.0 * f / FRAMES))       # rolls toward +x (clockwise on screen)
        R = tilt @ spin
        img = Image.new("RGBA", (16, 16), (0, 0, 0, 0))
        pxl = img.load()
        inside = np.zeros((16, 16), bool)
        for j in range(16):
            for i in range(16):
                dx, dy = (i + 0.5 - cx) / BALL_R, (cy - (j + 0.5)) / BALL_R
                d2 = dx * dx + dy * dy
                if d2 >= 1.0:
                    continue
                inside[j, i] = True
                n = np.array([dx, dy, math.sqrt(1 - d2)])
                inten = float(n @ L)
                k = 0 if inten > 0.80 else (1 if inten > 0.12 else (2 if inten > -0.35 else 3))
                if d2 > 0.80 and k < 2 and dx > -0.2:
                    k += 1                                         # rim darkening on the lit side keeps it round
                tones = body
                if panels is not None:
                    bn = R.T @ n
                    if (bn[0] > 0) != (bn[1] > 0):
                        tones = panels                             # two-tone: opposite quarters
                c = tones[k]
                # seams: two great circles (period 90 degrees of spin), 4 x 4 supersampled so they stay 1 px thin
                hits = 0
                for su in range(4):
                    for sv in range(4):
                        ex = (i + (su + 0.5) / 4 - cx) / BALL_R
                        ey = (cy - (j + (sv + 0.5) / 4)) / BALL_R
                        e2 = ex * ex + ey * ey
                        if e2 >= 1.0:
                            continue
                        bl = R.T @ np.array([ex, ey, math.sqrt(1 - e2)])
                        if abs(bl[0]) < 0.075 or abs(bl[1]) < 0.075:
                            hits += 1
                if hits >= 4:
                    c = seam_c[0] if k < 2 else seam_c[1]
                pxl[i, j] = c + (255,)
        # highlight: fixed at the upper left
        for (i, j) in ((5, 4), (6, 4), (5, 5)):
            if inside[j, i]:
                pxl[i, j] = hi_c + (255,) if (i, j) != (5, 5) else body[0] + (255,)
        # outline
        for j in range(16):
            for i in range(16):
                if inside[j, i]:
                    continue
                if any(0 <= a < 16 and 0 <= b < 16 and inside[b, a] for a, b in ((i - 1, j), (i + 1, j), (i, j - 1), (i, j + 1))):
                    pxl[i, j] = out_c + (255,)
        if st.get("sparkle") and f % 2 == 0:                       # a glint off the upper right edge
            gx, gy = 12, 3
            pxl[gx, gy] = (255, 255, 255, 255)
            for a, b in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                pxl[gx + a, gy + b] = body[0] + (255,)
        out.paste(img, (16 * f, 0))
    return out


def reward_outputs():
    """P8-06: {path: image} for the 2 reward court looks (floor + backdrop) and the 3 special balls."""
    out = {}
    for lid, (fl, bd) in REWARD_MAKERS.items():
        out[os.path.join(COURTS, lid + "_floor.png")] = fl()
        out[os.path.join(COURTS, lid + "_backdrop.png")] = bd()
    for bid, st in BALL_STYLES.items():
        out[os.path.join(BALLS, bid + ".png")] = ball_frames(st)
    return out


# ----------------------------------------------------------------------------- preview

def tile_test(img, n=4, zoom=2):
    w, h = img.size
    t = Image.new("RGB", (w * n, h * n))
    for a in range(n):
        for b in range(n):
            t.paste(img, (a * w, b * h))
    return t.resize((w * n * zoom, h * n * zoom), Image.NEAREST)


def load_frame(pid, col, row):
    path = os.path.join(ROOT, "assets", "players", pid + ".png")
    if not os.path.exists(path):
        return Image.new("RGBA", (40, 64), (0, 0, 0, 0))   # P6-25: v1 sheets removed; the v1 preview shows no players
    sh = Image.open(path).convert("RGBA")
    return sh.crop((col * 40, row * 64, col * 40 + 40, row * 64 + 64))


def ring(c):
    img = Image.new("RGBA", (40, 9), (0, 0, 0, 0))
    p = img.load()
    for j in range(9):
        for i in range(40):
            dx, dy = (i + 0.5 - 20) / 10.5, (j + 0.5 - 4.5) / 3.6
            d = math.sqrt(dx * dx + dy * dy)
            if 0.80 <= d <= 1.0:
                p[i, j] = c + (215,)
            elif 0.62 <= d < 0.80:
                p[i, j] = c + (110,)
            elif d < 0.62:
                p[i, j] = (10, 10, 30, 70)
    return img


def compose(look, floor, backdrop, ball, players):
    """One 3/4 frame as the game would show it: canvas pixels, then the ANGLED zoom (1.45) with nearest filtering.
    Sim -> canvas: x stays, y * TILT_Y (0.55); 12 px per foot; texel = 2 canvas px."""
    FT, TILT, ZOOM = 12.0, 0.55, 1.45
    cw, chh = int(1280 / ZOOM), int(720 / ZOOM)            # 882 x 496 canvas px on screen
    cv = Image.new("RGBA", (cw, chh), (0, 0, 0, 255))
    # world window: the left end of the court; sim x from -2 ft, the far sideline at canvas y = top_y
    x_off = 2 * FT
    far_y = 132                                             # canvas y of the far sideline
    near_y = far_y + int(50 * FT * TILT)                   # 330 px deeper
    apron = int(BACKDROP_BOTTOM_FT * FT * TILT)
    # backdrop (2x), repeated
    bd = backdrop.resize((BD_W * 2, BD_H * 2), Image.NEAREST)
    by = far_y - apron - BD_H * 2
    top_fill = backdrop.getpixel((0, 0))
    cv.paste(Image.new("RGBA", (cw, max(1, by)), top_fill + (255,)), (0, 0)) if by > 0 else None
    for x in range(-40, cw, BD_W * 2):
        cv.paste(bd, (x, by))
    # apron (darker floor) and the floor tile (2x)
    fl2 = floor.resize((TILE * 2, TILE * 2), Image.NEAREST)
    apron_col = {"gym": (122, 78, 44), "blacktop": (70, 86, 66)}[look]
    floor_rect = Image.new("RGBA", (cw, chh - (far_y - apron)), (0, 0, 0, 255))
    for x in range(0, cw, TILE * 2):
        for y in range(0, floor_rect.size[1], TILE * 2):
            floor_rect.paste(fl2, (x, y))
    if look == "gym":
        # apron: the same wood, a stained darker colour
        a = np.asarray(floor_rect).astype(float)
        mask = np.zeros(a.shape[:2], bool)
        mask[:apron] = True
        mask[:, :int(x_off)] = True
        a[mask, :3] = a[mask, :3] * 0.62 + np.array([60, 20, 10]) * 0.38
        floor_rect = Image.fromarray(a.astype(np.uint8), "RGBA")
    else:
        d = ImageDraw.Draw(floor_rect)
        d.rectangle([0, 0, cw, apron - 1], fill=apron_col + (255,))
        d.rectangle([0, 0, int(x_off) - 1, chh], fill=apron_col + (255,))
    cv.paste(floor_rect, (0, far_y - apron))
    d = ImageDraw.Draw(cv)

    def S(x, y):  # sim (feet) -> canvas
        return (x * FT + x_off, far_y + y * FT * TILT)

    line = (246, 240, 228, 255) if look == "gym" else (236, 236, 228, 255)
    paint = (47, 116, 224, 120) if look == "gym" else (216, 40, 58, 110)
    # key (paint), with alpha
    ov = Image.new("RGBA", cv.size, (0, 0, 0, 0))
    od = ImageDraw.Draw(ov)
    k0, k1 = S(0, 17), S(19, 33)
    od.rectangle([k0[0], k0[1], k1[0], k1[1]], fill=paint)
    cc = S(47, 25)
    od.ellipse([cc[0] - 6 * FT, cc[1] - 6 * FT * TILT, cc[0] + 6 * FT, cc[1] + 6 * FT * TILT], fill=paint)
    cv.alpha_composite(ov)
    lw = 2

    def ln(pts):
        d.line([S(*p) for p in pts], fill=line, width=lw)

    ln([(0, 0), (94, 0)])
    ln([(0, 0), (0, 50)])
    ln([(47, 0), (47, 50)])
    ln([(0, 17), (19, 17), (19, 33), (0, 33)])
    for a0, a1, cxy, r in (((0, 360), None, (19, 25), 6), ((0, 360), None, (47, 25), 6)):
        pts = [S(cxy[0] + r * math.cos(math.radians(t)), cxy[1] + r * math.sin(math.radians(t))) for t in range(0, 361, 6)]
        d.line(pts, fill=line, width=lw)
    hx = 5.25
    ang = math.degrees(math.asin(22.0 / 23.75))
    pts = [S(hx + 23.75 * math.cos(math.radians(t)), 25 + 23.75 * math.sin(math.radians(t))) for t in np.arange(-ang, ang + 0.1, 3)]
    d.line([S(0, 3)] + pts + [S(0, 47)], fill=line, width=lw)
    # hoop: pole behind the baseline, backboard, rim (simple stand-in for the code-drawn hoop)
    base = S(-1.5, 25)
    rim = S(hx, 25)
    rim_y = rim[1] - 10 * FT
    board_x = S(4, 25)[0]
    pole = (90, 94, 104, 255)
    d.rectangle([base[0] - 3, rim_y - 20, base[0] + 3, base[1]], fill=pole)
    d.rectangle([base[0] - 3, rim_y - 20, board_x, rim_y - 16], fill=pole)
    bw, bh = 3 * FT * TILT, 3.5 * FT
    d.rectangle([board_x - 3, rim_y - bh - 6, board_x + 3, rim_y + 10], fill=(240, 244, 248, 255), outline=(60, 64, 76, 255))
    d.rectangle([board_x - 2, rim_y - 22, board_x + 2, rim_y - 2], outline=(216, 40, 58, 255))
    d.ellipse([rim[0] - 9, rim_y - 4, rim[0] + 9, rim_y + 4], outline=(240, 118, 30, 255), width=2)
    for k in range(5):
        d.line([(rim[0] - 8 + k * 4, rim_y + 2), (rim[0] - 5 + k * 2.5, rim_y + 16)], fill=(250, 250, 250, 200))
    # shadow of the pole
    # players (2x) on the floor, depth-sorted by their floor y
    placed = []
    for pid, col, row, flip, (fx, fy), team in players:
        img = load_frame(pid, col, row)
        if flip:
            img = img.transpose(Image.FLIP_LEFT_RIGHT)
        sx, sy = S(fx, fy)
        placed.append((sy, sx, img, team, pid))
    for sy, sx, img, team, pid in sorted(placed):
        r = ring((64, 150, 255) if team == 0 else (236, 52, 64)).resize((80, 18), Image.NEAREST)
        cv.alpha_composite(r, (int(sx - 40), int(sy - 9)))
    for sy, sx, img, team, pid in sorted(placed):
        big = img.resize((80, 128), Image.NEAREST)
        cv.alpha_composite(big, (int(sx - 40), int(sy - 59 * 2)))
    # ball: one in flight toward the rim, frame 1
    b2 = ball.crop((16, 0, 32, 16)).resize((32, 32), Image.NEAREST)
    bx, byy = S(13, 23)
    sh = Image.new("RGBA", (22, 8), (0, 0, 0, 0))
    ImageDraw.Draw(sh).ellipse([0, 0, 21, 7], fill=(10, 10, 30, 80))
    cv.alpha_composite(sh, (int(bx - 11), int(byy - 4)))
    cv.alpha_composite(b2, (int(bx - 16), int(byy - 16 - 150)))
    hud = Image.new("RGBA", (cw, 37), (16, 14, 24, 170))   # the HUD top bar (54 screen px) covers this
    cv.alpha_composite(hud, (0, 0))
    return cv.resize((1280, 720), Image.NEAREST)


def city_outputs():
    """The 8 city looks: {path: image} for assets/courts/<look>_floor.png and <look>_backdrop.png."""
    out = {}
    for lid, (fl, bd) in CITY_MAKERS.items():
        out[os.path.join(COURTS, lid + "_floor.png")] = fl()
        out[os.path.join(COURTS, lid + "_backdrop.png")] = bd()
    return out


def label(img, text, x, y, scale=3, fg=(255, 255, 255), bg=(16, 14, 24)):
    """Big pixel text for the preview (uses PIL's default bitmap font, scaled up with nearest)."""
    d0 = ImageDraw.Draw(Image.new("RGB", (1, 1)))
    l, t, r, b = d0.textbbox((0, 0), text)
    small = Image.new("RGB", (r - l + 4, b - t + 4), bg)
    ImageDraw.Draw(small).text((2 - l, 2 - t), text, fill=fg)
    big = small.resize((small.size[0] * scale, small.size[1] * scale), Image.NEAREST)
    img.paste(big, (x, y))


def preview_v2(city, shots_dir):
    """docs/art/courts_preview_v2.png: per look, the game's own 1280 x 720 screenshot (from shots_dir/<look>.png,
    made with  -- --court <look> --shots), then the whole backdrop strip and the floor tile 3 x 3 at 2x."""
    looks = list(CITY_MAKERS.keys())
    strip_h = BD_H * 2
    tile_h = TILE * 3 * 2
    row_h = 720 + 8 + max(strip_h, tile_h) + 16
    pv = Image.new("RGB", (1280, row_h * len(looks)), (20, 18, 28))
    for n, lid in enumerate(looks):
        y0 = n * row_h
        shot = os.path.join(shots_dir, lid + ".png")
        if os.path.exists(shot):
            pv.paste(Image.open(shot).convert("RGB").resize((1280, 720), Image.NEAREST), (0, y0))
        bd = city[os.path.join(COURTS, lid + "_backdrop.png")]
        fl = city[os.path.join(COURTS, lid + "_floor.png")]
        pv.paste(bd.resize((BD_W * 2, strip_h), Image.NEAREST), (8, y0 + 728))
        t3 = tile_test(fl, n=3, zoom=2)
        pv.paste(t3, (1280 - t3.size[0] - 8, y0 + 728))
        name = CITY_LOOKS[lid]["name"]
        label(pv, name, 16, y0 + 728 + strip_h + 8, scale=4, fg=(255, 236, 160), bg=(20, 18, 28))
    pv.save(PREVIEW_V2, optimize=True)
    print("wrote", os.path.relpath(PREVIEW_V2, ROOT), pv.size, os.path.getsize(PREVIEW_V2), "bytes")


def rewards_preview(rew, shots_dir):
    """docs/art/rewards_preview.png (P8-06): per reward look, the game's own 1280 x 720 screenshot (shots_dir/<look>.png,
    from  -- --court <look> --shots) with its backdrop strip and floor tile 3 x 3; then the 3 special balls next to
    the game's ball, each frame at 8x and the ball at its in-game size (2x)."""
    looks = list(REWARD_MAKERS.keys())
    strip_h = BD_H * 2
    tile_h = TILE * 3 * 2
    row_h = 720 + 8 + max(strip_h, tile_h) + 16
    balls = ["ball"] + list(BALL_STYLES.keys())
    ball_row = 16 * 8 + 40
    pv = Image.new("RGB", (1280, row_h * len(looks) + 60 + ball_row * len(balls)), (20, 18, 28))
    for n, lid in enumerate(looks):
        y0 = n * row_h
        shot = os.path.join(shots_dir, lid + ".png") if shots_dir else ""
        if shot and os.path.exists(shot):
            pv.paste(Image.open(shot).convert("RGB").resize((1280, 720), Image.NEAREST), (0, y0))
        else:
            label(pv, "no screenshot: --rewards-preview DIR (DIR/%s.png)" % lid, 16, y0 + 340, scale=3)
        bd = rew[os.path.join(COURTS, lid + "_backdrop.png")]
        fl = rew[os.path.join(COURTS, lid + "_floor.png")]
        pv.paste(bd.resize((BD_W * 2, strip_h), Image.NEAREST), (8, y0 + 728))
        t3 = tile_test(fl, n=3, zoom=2)
        pv.paste(t3, (1280 - t3.size[0] - 8, y0 + 728))
        text = "%s  (%s, look %s)" % (REWARD_LOOKS[lid]["name"], REWARD_IDS[lid], lid)
        label(pv, text, 16, y0 + 728 + strip_h + 8, scale=3, fg=(255, 236, 160), bg=(20, 18, 28))
    y = row_h * len(looks) + 16
    label(pv, "BALLS: 4 spin frames of 16 x 16 at 8x, then the ball at 2x (in-game size)", 16, y, scale=2,
          fg=(255, 236, 160), bg=(20, 18, 28))
    y += 44
    for bid in balls:
        img = ball_frames() if bid == "ball" else rew[os.path.join(BALLS, bid + ".png")]
        big = Image.new("RGBA", img.size, H("#3a3650") + (255,))
        big.alpha_composite(img)
        pv.paste(big.convert("RGB").resize((16 * FRAMES * 8, 16 * 8), Image.NEAREST), (16, y))
        for f in range(FRAMES):                                   # in-game size on two floors
            for k, bgc in enumerate((H("#e2b870"), H("#2b2d45"))):
                cell = Image.new("RGBA", (16, 16), bgc + (255,))
                cell.alpha_composite(img.crop((16 * f, 0, 16 * f + 16, 16)))
                pv.paste(cell.convert("RGB").resize((32, 32), Image.NEAREST), (560 + f * 40, y + 10 + k * 48))
        name = "ORANGE (ball.png, default)" if bid == "ball" else "%s  (%s)" % (BALL_STYLES[bid]["name"], bid)
        label(pv, name, 740, y + 40, scale=3, fg=(255, 255, 255), bg=(20, 18, 28))
        y += ball_row
    pv.save(REWARDS_PREVIEW, optimize=True)
    print("wrote", os.path.relpath(REWARDS_PREVIEW, ROOT), pv.size, os.path.getsize(REWARDS_PREVIEW), "bytes")


def write_rewards(args):
    """The P8-06 outputs (2 court looks, 3 balls); --rewards-preview DIR also composes docs/art/rewards_preview.png."""
    os.makedirs(COURTS, exist_ok=True)
    os.makedirs(BALLS, exist_ok=True)
    rew = reward_outputs()
    for path, img in rew.items():
        img.save(path, optimize=True)
        print("wrote %s %s %d bytes" % (os.path.relpath(path, ROOT), img.size, os.path.getsize(path)))
    if "--rewards-preview" in args:
        i = args.index("--rewards-preview")
        rewards_preview(rew, args[i + 1] if i + 1 < len(args) else None)


def main():
    args = sys.argv[1:]
    if "--print-looks" in args:
        print(looks_gdscript())
        return
    if "--rewards" in args or "--rewards-preview" in args:
        write_rewards(args)                       # only the P8-06 files (the other textures are left as they are)
        return
    if "--era" in args or "--era-preview" in args or "--era-sheet" in args:
        write_era(args)                           # only the era looks (the other textures are left as they are)
        return
    shots_dir = None
    if "--shots" in args:
        shots_dir = args[args.index("--shots") + 1]
    os.makedirs(COURTS, exist_ok=True)
    os.makedirs(BALLS, exist_ok=True)
    city = city_outputs()
    for path, img in city.items():
        img.save(path, optimize=True)
        print("wrote %s %s %d bytes" % (os.path.relpath(path, ROOT), img.size, os.path.getsize(path)))
    if shots_dir:
        preview_v2(city, shots_dir)
    else:
        print("courts_preview_v2.png not rebuilt (needs game screenshots: --shots DIR, see the top of this file)")
    v1_main()
    write_rewards(args)
    write_era(args)


def v1_main():
    os.makedirs(COURTS, exist_ok=True)
    os.makedirs(BALLS, exist_ok=True)
    out = {
        os.path.join(COURTS, "gym_floor.png"): gym_floor(),
        os.path.join(COURTS, "blacktop_floor.png"): blacktop_floor(),
        os.path.join(COURTS, "gym_backdrop.png"): gym_backdrop(),
        os.path.join(COURTS, "blacktop_backdrop.png"): blacktop_backdrop(),
        os.path.join(BALLS, "ball.png"): ball_frames(),
    }
    for path, img in out.items():
        img.save(path, optimize=True)
        print("wrote %s %s %d bytes" % (os.path.relpath(path, ROOT), img.size, os.path.getsize(path)))
    imgs = list(out.values())
    gym_f, top_f, gym_b, top_b, ball = imgs
    # seam test: each floor tile 4 x 4
    a, b = tile_test(gym_f), tile_test(top_f)
    t = Image.new("RGB", (a.size[0] * 2 + 16, a.size[1]), (28, 26, 38))
    t.paste(a, (0, 0))
    t.paste(b, (a.size[0] + 16, 0))
    t.save(TILES_TEST, optimize=True)
    print("wrote", os.path.relpath(TILES_TEST, ROOT))
    # preview: both looks; players use the frames the sheets have now
    cast = [  # id, column, row, mirrored, (x ft, y ft), team
        ("blue_1", 10, 1, False, (24, 30), 0),       # dribbling toward the hoop? (SE dribble)
        ("red_1", 0, 2, True, (17, 27), 1),          # guarding, facing W? mirrored E = W
        ("red_2", 4, 3, True, (30, 12), 1),          # running NW (far side)
        ("blue_2", 0, 0, False, (34, 42), 0),        # standing near the camera
        ("blue_3", 5, 1, True, (9, 38), 0),          # running SW
        ("red_3", 1, 4, False, (8, 15), 1),          # back to the camera, far side
    ]
    p1 = compose("gym", gym_f, gym_b, ball, cast)
    p2 = compose("blacktop", top_f, top_b, ball, cast)
    strip_h = int(BD_H * 1.6)
    pv = Image.new("RGB", (1280, 1440 + 16 + strip_h + 8), (20, 18, 28))
    pv.paste(p1.convert("RGB"), (0, 0))
    pv.paste(p2.convert("RGB"), (0, 728))
    # the two whole backdrops (most of their top half is above the camera or under the HUD in game)
    for k, bd in enumerate((gym_b, top_b)):
        pv.paste(bd.resize((int(BD_W * 1.6), strip_h), Image.NEAREST), (k * 644 + 6, 1456))
    # ball frames, enlarged, in a corner
    bf = ball.resize((64 * 6, 16 * 6), Image.NEAREST)
    pad = Image.new("RGBA", (bf.size[0] + 12, bf.size[1] + 12), (20, 18, 28, 230))
    pad.alpha_composite(bf, (6, 6))
    pv.paste(pad.convert("RGB"), (1280 - pad.size[0] - 8, 1440 - pad.size[1] - 8))
    pv.save(PREVIEW, optimize=True)
    print("wrote", os.path.relpath(PREVIEW, ROOT))


if __name__ == "__main__":
    main()
